SourceCode.Declaration:
/// <summary>
/// Extension of the <c>WHSParameters</c> form for the AAXWarehouseTools model. Applies the label
/// preview parameter defaults to an existing parameters record when the form opens.
/// </summary>
[ExtensionOf(formStr(WHSParameters))]
final class WHSParametersForm_AAXWarehouseTools_Extension
{
}

Method.Source:
/// <summary>
/// Extends <c>init</c> to apply the label preview parameter defaults to an existing parameters
/// record after the base implementation is called with <c>next</c>. Skipped when the user has
/// no edit access.
/// </summary>
public void init()
{
    WHSParameters parameters;

    next init();

    // Skip without edit access
    if (!hasTableAccess(tableNum(WHSParameters), AccessType::Edit))
    {
        return;
    }

    ttsbegin;
    select forupdate firstonly parameters;

    if (parameters
        && (!parameters.AAXPreviewAutoOffDays
         || !parameters.AAXPreviewRetentionDays
         || !parameters.AAXPreviewDefaultDpi
         || !parameters.AAXPreviewDefaultWidthIn
         || !parameters.AAXPreviewDefaultHeightIn))
    {
        parameters.aaxApplyPreviewDefaultsIfUnset();
        parameters.update();
    }
    ttscommit;
}
